import{_ as t,o as n,c as a,ag as d}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"/nay Panel","description":"","frontmatter":{},"headers":[],"relativePath":"de/nay-lib/panel.md","filePath":"de/nay-lib/panel.md"}'),r={name:"de/nay-lib/panel.md"};function i(l,e,o,s,c,h){return n(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="nay-panel" tabindex="-1">/nay Panel <a class="header-anchor" href="#nay-panel" aria-label="Permalink to &quot;/nay Panel&quot;">​</a></h1><p>Gib im Spiel <code>/nay</code> ein, um das Einstellungspanel zu öffnen. Du siehst jedes Nayretis Skript, das du konfigurieren darfst. Spieler mit <code>nay.admin</code> sehen außerdem den Bereich <strong>Server</strong>: die Seite Nayretis, Berechtigungen, API, Webhooks und Protokoll.</p><p>Einstellungen werden in der Datenbank gespeichert. Wenn du auf <strong>Speichern</strong> drückst, wird der neue Wert geprüft, gespeichert, ins <a href="/de/nay-lib/audit">Protokoll</a> geschrieben und sofort für jeden verbundenen Spieler übernommen. Kein Neustart nötig.</p><p>Manche Skriptseiten haben auch Aktionsschaltflächen, zum Beispiel <strong>Waschstraßen verwalten</strong> auf der Seite Car Wash.</p><h2 id="nayretis-einstellungen" tabindex="-1">Nayretis Einstellungen <a class="header-anchor" href="#nayretis-einstellungen" aria-label="Permalink to &quot;Nayretis Einstellungen&quot;">​</a></h2><p>Die Seite <strong>Nayretis</strong> enthält die Einstellungen, die für alle Skripte gelten.</p><p>Die Spalte <strong>In /nay</strong> zeigt den Namen, der im Panel angezeigt wird. Der Schlüssel ist der Name, den <code>config.lua</code> und die <a href="/de/nay-lib/api">HTTP-API</a> verwenden.</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Sprache</td><td><code>Locale</code></td><td>Sprache</td><td>Englisch oder der Wert von <code>nay:locale</code></td><td>Sprache aller Nayretis Skripte: Englisch, Französisch, Spanisch, Portugiesisch, Polnisch oder Deutsch.</td></tr><tr><td>Oberflächendesign</td><td><code>Theme</code></td><td><code>graphite</code> oder <code>papier</code></td><td><code>graphite</code></td><td>Aussehen der Nayretis Oberflächen: dunkel (Graphite) oder hell (Papier).</td></tr><tr><td>HTTP-API</td><td><code>ApiEnabled</code></td><td>an / aus</td><td>aus</td><td>Aktiviert die <a href="/de/nay-lib/api">HTTP-API</a>. Solange sie aus ist, antwortet jede Route mit <code>503 api_disabled</code>.</td></tr><tr><td>Maximale Anfragegröße (KB)</td><td><code>ApiMaxBodyKb</code></td><td>Zahl, 1 bis 10240</td><td>1024</td><td>Größter Anfrageinhalt, den die API annimmt, in KB.</td></tr><tr><td>Aufbewahrung des Protokolls (Tage)</td><td><code>AuditRetentionDays</code></td><td>Zahl, 0 bis 3650</td><td>90</td><td>Ältere Protokolleinträge werden täglich gelöscht. 0 behält alles.</td></tr></tbody></table><h2 id="wer-das-panel-offnen-darf" tabindex="-1">Wer das Panel öffnen darf <a class="header-anchor" href="#wer-das-panel-offnen-darf" aria-label="Permalink to &quot;Wer das Panel öffnen darf&quot;">​</a></h2><ul><li><code>nay.admin</code> gibt alles frei.</li><li><code>nay.config</code> gibt die Einstellungen aller Skripte frei.</li><li><code>nay.audit</code> öffnet das Panel auf dem Protokoll.</li><li><code>&lt;resource&gt;.config</code> gibt die Einstellungen eines Skripts frei, zum Beispiel <code>nay_car_wash.config</code>.</li></ul><p>Wie du sie vergibst, steht unter <a href="/de/nay-lib/permissions">Berechtigungen</a>.</p>',11)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
